\begin{align} \frac{1}{\gamma_{j}(t) - \gamma_i(t) + (\gamma_{i}(t) - \gamma_{i+1}(t))} - \frac{1}{\gamma_{j}(t) - \gamma_i(t)}\geq \frac{1}{\xi_{j}(t) - \xi_i(t) + (\gamma_{i}(t) - \gamma_{i+1}(t))} - \frac{1}{\xi_{j}(t) - \xi_i(t)}.
