and that, for all $1\leq i \leq \frac{d}{2} +1$,

\begin{equation} \frac{\omega_i}{\sqrt{d}} - \frac{\omega_{i+1}}{\sqrt{d}} \geq \frac{1}{d\times \rho(\omega_{i+1})} \stackrel{\textrm{Eq. \eqref{eq_a13b}}}{\geq} \frac{1}{2d     \frac{1}{2\pi} \sqrt{2-\omega_{i+1}}} \stackrel{\textrm{Eq. \eqref{eq_a8b}}}{\geq}  \frac{1}{2d     \frac{1}{2\pi} \sqrt{     \frac{9}{2}d^{-\frac{2}{3}} i^{\frac{2}{3}}}} \geq \frac{\pi}{\sqrt{ \frac{9}{2}}} d^{-\frac{2}{3}}i^{-\frac{1}{3}}.
